398	// via `mockUseIntersectionObserver.mockReturnValueOnce(true)` — a per-test override that leaves
399	// every test above completely unaffected (the mock's own default return stays `false`).
400	describe('RecommendedProducts — impression tracking (PostBuild fix round, Fix 1, 2026-09-15)', () => {
401	  test('Recently-Viewed: when every rec fails to map, no impression is reported at all', () => {
402	    // The exact bug Fix 1 closes: every one of this shopper's recently-viewed products fails
403	    // `selectRecentlyViewedCard`'s null-gate (e.g. no usable name/image), so the rail correctly
404	    // renders nothing — but before this fix, the impression-tracking effect ran ahead of that
405	    // filtering and still reported every raw id in `recommendations.recs` as "viewed": false signal
406	    // into Einstein/DataCloud's own feedback loop, with nothing on screen to indicate it happened.
407	    //
408	    // Verified directly, not just asserted (this codebase's own prove-don't-assert discipline —
409	    // matches recentlyViewed/index.test.tsx's own "all-stale-history gate" test): temporarily
410	    // reverting index.tsx's impression-tracking effect back to its pre-Fix-1 form (mapping
411	    // `recommendations.recs` directly, with no recommender branch) makes this exact test fail —
412	    // both `mockSendViewReco` and `mockSendViewRecommendations` are called, with the two ids that
413	    // never actually rendered — and restoring Fix 1 makes it pass again.
414	    const mockSendViewReco = vi.fn();
415	    mockUseEinstein.mockReturnValue({
416	      isLoading: false,
417	      recommendations: buildRecentlyViewedRecommendations(mockRecentlyViewedProducts),
418	      getZoneRecommendations: vi.fn(),
419	      getRecommendations: vi.fn(),
420	      sendClickReco: vi.fn(),
421	      sendViewReco: mockSendViewReco,
422	    });
423	    // Both fixture products fail the mapper's own hard gate — the scenario Fix 1 exists for.
424	    mockSelectRecentlyViewedCard.mockReturnValue(null);
425	    mockUseIntersectionObserver.mockReturnValueOnce(true);
426	
427	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, title: 'Recently Viewed' });
428	
429	    // The mapping was attempted (proves this is "attempted and filtered", not "never ran") ...
430	    expect(mockSelectRecentlyViewedCard).toHaveBeenCalled();
431	    // ... but nothing survived it, so no impression was reported at all.
432	    expect(mockSendViewReco).not.toHaveBeenCalled();
433	    expect(mockSendViewRecommendations).not.toHaveBeenCalled();
434	  });
435	
436	  test('any other recommender still reports the full raw recs list on impression, unchanged', () => {
437	    // Confirms Fix 1's recommender branch is genuinely additive, not a regression for the other
438	    // four recommenders: a non-Recently-Viewed recommender has no `selectRecentlyViewedCard`
439	    // filtering step in this component at all, so its reported id list must still be the full, raw
440	    // `recommendations.recs` mapped straight to `{ id }` — the exact pre-Fix-1 expression, now the
441	    // untouched `else` branch of index.tsx's own `ids` ternary.
442	    const mockSendViewReco = vi.fn();
443	    const otherRecommendations = {
444	      recommenderName: 'might-also-like-einstein',
445	      recoUUID: 'test-other-reco-uuid',
446	      displayMessage: 'You Might Also Like',
447	      recs: [
448	        { id: 'other-1', name: 'Recommended One' },
449	        { id: 'other-2', name: 'Recommended Two' },
450	      ],
451	    };
452	    mockUseEinstein.mockReturnValue({
453	      isLoading: false,
454	      recommendations: otherRecommendations,
455	      getZoneRecommendations: vi.fn(),
456	      getRecommendations: vi.fn(),
457	      sendClickReco: vi.fn(),
458	      sendViewReco: mockSendViewReco,
459	    });
460	    mockUseIntersectionObserver.mockReturnValueOnce(true);
461	
462	    renderRecommendedProducts({ recommender: EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE });
463	
464	    expect(mockSelectRecentlyViewedCard).not.toHaveBeenCalled();
465	    const expectedIds = [{ id: 'other-1' }, { id: 'other-2' }];
466	    const expectedRecoMeta = { recommenderName: 'might-also-like-einstein', __recoUUID: 'test-other-reco-uuid' };
467	    expect(mockSendViewReco).toHaveBeenCalledWith(expectedRecoMeta, expectedIds);
